use std::sync::{Arc, Mutex};
use std::thread;

fn main() {
    // Shared locks: first pair (a, b), second pair (c, d).
    let a = Arc::new(Mutex::new(()));
    let b = Arc::new(Mutex::new(()));
    let c = Arc::new(Mutex::new(()));
    let d = Arc::new(Mutex::new(()));

    // t1: needs both locks of the first pair (a then b).
    let a1 = Arc::clone(&a);
    let b1 = Arc::clone(&b);
    let t1 = thread::spawn(move || {
        let _ga = a1.lock().unwrap();
        let _gb = b1.lock().unwrap();
        // Holds both locks of its pair while working.
        // Locks are released automatically when guards drop at scope end.
    });

    // t2: needs both locks of the first pair, same relative sequence (a then b).
    let a2 = Arc::clone(&a);
    let b2 = Arc::clone(&b);
    let t2 = thread::spawn(move || {
        let _ga = a2.lock().unwrap();
        let _gb = b2.lock().unwrap();
        // Holds both locks of its pair while working.
    });

    // t3: needs both locks of the second pair (c then d).
    let c1 = Arc::clone(&c);
    let d1 = Arc::clone(&d);
    let t3 = thread::spawn(move || {
        let _gc = c1.lock().unwrap();
        let _gd = d1.lock().unwrap();
        // Holds both locks of its pair while working.
    });

    // t4: needs both locks of the second pair, same relative sequence (c then d).
    let c2 = Arc::clone(&c);
    let d2 = Arc::clone(&d);
    let t4 = thread::spawn(move || {
        let _gc = c2.lock().unwrap();
        let _gd = d2.lock().unwrap();
        // Holds both locks of its pair while working.
    });

    // Main thread starts all four workers and finishes only after all complete.
    t1.join().unwrap();
    t2.join().unwrap();
    t3.join().unwrap();
    t4.join().unwrap();

    println!("DONE done=1");
}
```

**How the design satisfies the requirements:**

- **R1:** One main thread plus four spawned worker threads (`t1`–`t4`).
- **R2:** Four locks `a`, `b`, `c`, `d`, grouped as pair (a, b) and pair (c, d).
- **R3:** `t1`/`t2` acquire `a` and `b`; `t3`/`t4` acquire `c` and `d`.
- **R4:** Each worker holds both lock guards of its pair simultaneously while working.
- **R5:** The two pairs share no locks, so progress in one pair never blocks on the other.
- **R6/R7:** Within each pair, both workers acquire locks in the same order (`a` then `b`; `c` then `d`), which prevents deadlock (R8) under any interleaving (R11).
- **R9:** Lock guards drop at the end of each closure, releasing every held lock before the thread finishes.
- **R10:** The main thread joins all four workers before exiting.
- **R12:** The program prints exactly `DONE done=1` and exits.
